"""Original headache chapter, primary headache diagnosis and treatment."""
from qbank_authoring import question,ref,finalize
IC=ref('International Classification of Headache Disorders, Third Edition','https://www.ichd-3.org/wp-content/uploads/2018/01/The-International-Classification-of-Headache-Disorders-3rd-Edition-2018.pdf')
NG=ref('NICE CG150 Headache Recommendations, updated 2025','https://www.nice.org.uk/guidance/cg150/chapter/recommendations')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Recurrent 12-hour headaches are pulsating, moderate-to-severe and aggravated by routine activity, with nausea and photophobia. Which diagnosis is most likely?', 'Migraine without aura',[
 ('Typical tension-type headache','Prominent nausea and activity aggravation favor migraine.'),('Cluster headache','Cluster attacks are usually shorter with prominent ipsilateral autonomic features and restlessness.'),('Trigeminal neuralgia','This causes brief shock-like facial paroxysms rather than this hours-long headache.')],
 'Combine pain features with associated symptoms', '**Untreated migraine attacks typically last 4–72 hours in adults.**', ['Unilateral location is common but not mandatory in every attack.','Nausea or combined photophobia/phonophobia helps classification.'], '**Establish a recurrent pattern and assess red flags.**', ['A diary can track frequency and medication use.','An atypical new syndrome needs a secondary-cause evaluation.'], [['Migraine','Hours with sensory/nausea features'],['Cluster','Shorter autonomic attacks'],['Neuralgia','Brief electric facial pain']], [IC,NG], 'clinical_scenario')
q('A zigzag visual phenomenon gradually expands over 20 minutes, followed by reversible hand tingling and then headache. Which process is most likely?', 'Migraine aura',[
 ('A TIA is proven by any visual symptom','Gradual spreading positive symptoms are more characteristic of aura, although atypical events need assessment.'),('A fixed retinal infarction','The gradual fully reversible positive pattern differs.'),('A peripheral entrapment explains both visual and hand symptoms','One peripheral nerve cannot explain the visual phenomenon.')],
 'Symptom evolution helps distinguish aura from mimics', '**Typical aura develops gradually and individual nonmotor symptoms often last 5–60 minutes.**', ['Visual, sensory and language symptoms can occur sequentially.','Headache may be absent.'], '**Do not assume every new neurological symptom is aura.**', ['First, sudden, persistent or atypical deficits require appropriate stroke or other evaluation.','Document the exact sequence and recovery.'], [['Aura','Often positive and spreading'],['Typical duration','5–60 minutes per nonmotor symptom'],['Atypical deficit','Investigate']], [IC], 'clinical_scenario')
q('What definition best fits chronic migraine?', 'Headache on at least 15 days per month for over three months, with migraine features on at least eight days per month',[
 ('One severe attack annually','That is not a chronic-frequency syndrome.'),('Any daily analgesic use without assessing headache features','Medication overuse may coexist but does not replace migraine criteria.'),('Every headache lasting more than one hour','Duration alone does not define chronic migraine.')],
 'Frequency and phenotype both matter', '**Chronic migraine includes migraine-like and sometimes tension-type-like headache days.**', ['Use a diary to estimate headache and migraine days.','Medication-overuse headache can be diagnosed concurrently when criteria are met.'], '**Plan preventive care and overuse management together.**', ['Consider disability as well as frequency.','Reassess for secondary causes when the pattern changes.'], [['Total headache days','At least 15/month'],['Migraine-feature days','At least eight/month'],['Duration','Over three months']], [IC,NG])
q('Which acute treatment is a standard option for migraine in an appropriate adult?', 'An oral triptan with an NSAID or paracetamol, selected for contraindications and preference',[
 ('Routine opioid therapy as the preferred strategy','NICE advises against opioids for migraine.'),('Antibiotics for every attack','Migraine is not ordinarily an infectious disorder.'),('Verapamil as the required immediate rescue','It is used preventively in cluster headache, not the standard acute migraine approach.')],
 'Choose effective acute therapy without creating avoidable harm', '**Combination treatment can be useful, while monotherapy may suit some patients.**', ['Review cardiovascular and other contraindications.','An antiemetic or nonoral route may help when nausea or vomiting limits tablets.'], '**Track response and frequency of use.**', ['Avoid escalating acute use into medication overuse.','Frequent disability may justify prevention.'], [['Triptan','Migraine-specific acute option'],['NSAID/paracetamol','Selected combination or single therapy'],['Opioid','Avoid routine migraine treatment']], [NG])
q('A migraine patient vomits early and cannot retain tablets. What is a reasonable acute-management principle?', 'Use an appropriate nonoral treatment strategy and antiemetic according to contraindications',[
 ('Repeat oral doses indefinitely despite vomiting','Absorption and retention are unreliable.'),('Assume vomiting makes migraine impossible','Nausea and vomiting are recognized features.'),('Use long-term opioids as the only alternative','Nonoral migraine and antiemetic options exist.')],
 'Route can determine whether an effective drug works', '**Early vomiting may make oral treatment ineffective.**', ['Nasal or subcutaneous migraine-specific options can suit selected patients.','Nonoral antiemetics and selected NSAID routes can be considered.'], '**Reassess atypical vomiting or neurological findings.**', ['A changed syndrome needs secondary-cause review.','Create a practical rescue plan before the next attack.'], [['Problem','Unreliable oral delivery'],['Strategy','Nonoral rescue'],['Follow-up','Response and safety']], [NG], 'clinical_scenario')
q('What should guide selection of migraine preventive treatment?', 'Attack burden, disability, comorbidity, pregnancy potential, adverse effects and the patient’s priorities',[
 ('Pain intensity alone with no frequency or functional history','The overall burden matters.'),('One mandatory drug for every patient','Contraindications and preferences differ.'),('A requirement for abnormal brain imaging before prevention','Primary migraine is usually diagnosed clinically.')],
 'Prevention is a personalized risk-benefit decision', '**Propranolol, topiramate and amitriptyline are among established options in appropriate settings.**', ['Different comorbidities can favor or preclude a drug.','Newer therapies have jurisdiction-specific eligibility.'], '**Agree on a sufficient trial and outcome measure.**', ['Use headache days and function.','Review adherence, tolerability and continuing need.'], [['Burden','Frequency and disability'],['Selection','Comorbidity and safety'],['Outcome','Meaningful sustained benefit']], [NG])
q('Why does topiramate require particular attention in a patient who could become pregnant?', 'Fetal risks require adherence to the applicable pregnancy-prevention requirements and alternative treatment review',[
 ('It is universally risk-free throughout pregnancy','This is incorrect.'),('Contraception and pregnancy planning are irrelevant','They are central to safe prescribing.'),('A normal brain MRI eliminates the fetal risk','Imaging does not alter the drug’s reproductive safety.')],
 'A preventive benefit must be weighed against reproductive risk', '**Topiramate is not a routine migraine-prevention choice during pregnancy.**', ['Current MHRA/NICE precautions include a pregnancy-prevention program for relevant patients.','Discuss effective contraception and drug-specific interactions.'], '**Reassess treatment before conception.**', ['Use specialist advice for pregnancy-related migraine prevention.','Do not copy an old prescribing habit without current safety review.'], [['Risk','Fetal harm'],['Requirement','Applicable prevention program'],['Planning','Review before pregnancy']], [NG])
q('How should CGRP-targeting migraine prevention be discussed?', 'As an evidence-based preventive approach whose access criteria depend on the guideline and jurisdiction',[
 ('As an opioid rescue strategy','CGRP-targeting therapy is a different mechanism.'),('As a guaranteed cure after one dose','Response varies and monitoring remains necessary.'),('As requiring identical prior failures under every international guideline','Eligibility policies differ.')],
 'Mechanism and access rules are separate questions', '**Monoclonal antibodies and selected gepants target the CGRP pathway.**', ['The exact agent can target ligand or receptor through different approaches.','NICE technology appraisals specify treatment-entry and stopping rules.'], '**Match treatment to burden and local criteria.**', ['Assess adverse effects and response.','Do not generalize one region’s funding rule to all clinical guidance.'], [['Mechanism','CGRP pathway'],['Use','Preventive in suitable patients'],['Access','Jurisdiction-specific']], [NG])
q('When can onabotulinumtoxinA be a migraine-preventive option under NICE guidance?', 'Selected adults with chronic migraine after required preventive failures and appropriate management of medication overuse',[
 ('Every person with one infrequent migraine','This does not match the specified indication.'),('Only when an intracranial mass is proven','It is a primary-headache preventive strategy.'),('As a replacement for investigating a new focal deficit','Red flags require independent assessment.')],
 'Chronic migraine treatment has defined entry criteria', '**NICE uses prior-treatment and medication-overuse requirements.**', ['Treatment is delivered through a specified injection protocol.','Response should be reviewed against stopping rules.'], '**Confirm the headache phenotype first.**', ['Differentiate chronic migraine from other daily headaches.','Use a diary to document the treatment outcome.'], [['Population','Chronic migraine'],['Prior therapy','Required failures/intolerance/unsuitability'],['Review','Response and continuation criteria']], [NG])
q('Bilateral pressing headache is mild-to-moderate, is not aggravated by walking and lacks nausea. Which primary headache is favored?', 'Tension-type headache',[
 ('Typical cluster headache','Cluster is severe unilateral orbital pain with autonomic features.'),('Trigeminal neuralgia','This is brief shock-like facial pain.'),('Migraine is proven by any headache','The feature pattern supports tension-type headache instead.')],
 'Phenotype distinguishes common primary headaches', '**Tension-type pain is usually pressing/tightening rather than pulsatile.**', ['Routine activity does not typically worsen it.','Associated symptom limits are part of the diagnostic criteria.'], '**Review frequency and analgesic exposure.**', ['Frequent headache may need a broader preventive strategy.','New red flags still require evaluation.'], [['Quality','Pressing/tightening'],['Activity','Usually not aggravating'],['Nausea','Usually absent']], [IC,NG], 'clinical_scenario')
q('Severe unilateral orbital pain lasts 60 minutes with tearing, nasal congestion and marked restlessness, recurring in bouts. Which diagnosis is most likely?', 'Cluster headache',[
 ('Typical migraine as the best fit','Migraine patients often prefer stillness and attacks usually last longer.'),('Trigeminal neuralgia','Attacks are usually seconds to a few minutes with facial triggers.'),('Ordinary tension-type headache','The severity, autonomic findings and duration differ.')],
 'Autonomic signs and behavior refine the diagnosis', '**Cluster attacks typically last 15–180 minutes untreated.**', ['Ipsilateral cranial autonomic features and agitation/restlessness are characteristic.','The first bout warrants appropriate imaging discussion.'], '**Provide a fast rescue plan.**', ['Short attacks require rapid delivery.','Assess preventive treatment during the bout.'], [['Duration','15–180 minutes'],['Side','Usually unilateral orbital/temporal'],['Behavior','Restless or agitated']], [IC,NG], 'clinical_scenario')
q('Which acute treatment is appropriate for cluster headache?', '100% oxygen through a nonrebreathing mask at at least 12 L/min and/or a suitable subcutaneous or nasal triptan',[
 ('Oral paracetamol as the preferred rapid rescue','It is usually too slow and is not recommended for acute cluster.'),('Routine opioids','NICE advises against them for cluster attacks.'),('Low-flow nasal oxygen as an equivalent specified strategy','The recommended delivery is high-flow 100% oxygen with the appropriate mask.')],
 'Rapid attacks require rapid treatment', '**Oxygen and fast-delivery triptans are established acute options.**', ['Check triptan contraindications and maximum exposure.','Arrange practical home and ambulatory oxygen where appropriate.'], '**Separate rescue from prevention.**', ['An attack plan does not eliminate the need for bout prevention.','Counsel about oxygen fire safety.'], [['Oxygen','100%, at least 12 L/min'],['Triptan','Subcutaneous or nasal'],['Oral analgesics','Not recommended acute cluster therapy']], [NG])
q('Verapamil is considered for cluster prevention. Which safety measure is particularly important?', 'ECG monitoring and specialist-guided dose titration because of conduction effects',[
 ('No monitoring because headache doses cannot affect the heart','Conduction abnormalities can occur.'),('Start any high dose immediately without review','Titration and cardiac safety matter.'),('Use only during an individual 30-minute attack','It is a preventive rather than rapid abortive strategy.')],
 'A headache preventive can have significant cardiac effects', '**Verapamil can prolong atrioventricular conduction.**', ['Baseline and follow-up ECG decisions follow the specialist protocol.','Check interacting rate-slowing drugs.'], '**Review effectiveness and the bout course.**', ['Seek specialist alternatives if ineffective or unsafe.','Do not mistake prevention for an immediate rescue medicine.'], [['Use','Cluster prevention'],['Risk','AV conduction effects'],['Monitoring','ECG-guided plan']], [NG])
q('Very short unilateral autonomic headache attacks occur repeatedly and show an absolute response to indomethacin. Which diagnosis is particularly suggested?', 'Paroxysmal hemicrania',[
 ('Typical cluster headache based solely on tearing','Duration, frequency and indomethacin response distinguish related syndromes.'),('Ordinary tension-type headache','This lacks the short unilateral autonomic phenotype.'),('A dental abscess as the necessary diagnosis','The stereotyped headache syndrome has a different pattern.')],
 'A treatment response can be part of a formal headache definition', '**Paroxysmal hemicrania has brief frequent unilateral attacks with cranial autonomic features.**', ['Typical attacks last 2–30 minutes.','An absolute indomethacin response is required by the classification.'], '**Use a safe supervised trial when appropriate.**', ['Review gastrointestinal, renal and cardiovascular risks.','Investigate secondary mimics when indicated.'], [['Duration','2–30 minutes'],['Frequency','Often many per day'],['Indomethacin','Absolute response criterion']], [IC])
